//! r6-timers: run r6 services periodically (the r6 counterpart of systemd timers,
//! generated by `r6-import` from `.timer` units).
//!
//!   r6-timers [CONFIG] [--state DIR]
//!
//! CONFIG (default /etc/r6/timers.toml) lists `[[timer]]` tables with `name`,
//! `service`, `interval_s` (0: once per boot), `boot_delay_s` and `persistent`.
//! The last run of each timer is kept in DIR (default /var/lib/r6/timers), so
//! intervals continue across reboots; a persistent timer that missed its run while
//! the machine was off runs `boot_delay_s` after boot.

use serde::Deserialize;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Deserialize)]
struct Config {
    #[serde(default)]
    timer: Vec<Timer>,
}

#[derive(Deserialize, Clone)]
struct Timer {
    name: String,
    service: String,
    interval_s: u64,
    #[serde(default = "default_delay")]
    boot_delay_s: u64,
    #[serde(default)]
    persistent: bool,
}

fn default_delay() -> u64 {
    300
}

fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn last_run(state: &Path, name: &str) -> Option<u64> {
    std::fs::read_to_string(state.join(name))
        .ok()?
        .trim()
        .parse()
        .ok()
}

/// When a timer is next due (epoch seconds), given the supervisor start time.
fn due(t: &Timer, last: Option<u64>, started: u64, ran_this_boot: bool) -> Option<u64> {
    let earliest = started + t.boot_delay_s;
    if t.interval_s == 0 {
        // Once per boot.
        return (!ran_this_boot).then_some(earliest);
    }
    match last {
        Some(l) => {
            let next = l + t.interval_s;
            if next <= started && !t.persistent {
                // Missed while off: not persistent, so wait one interval from boot.
                Some(started + t.interval_s)
            } else {
                Some(next.max(earliest))
            }
        }
        None => Some(started + t.interval_s.min(86400).max(t.boot_delay_s)),
    }
}

fn main() {
    let mut config = PathBuf::from("/etc/r6/timers.toml");
    let mut state = PathBuf::from("/var/lib/r6/timers");
    let mut args = std::env::args().skip(1);
    while let Some(a) = args.next() {
        match a.as_str() {
            "--state" => state = args.next().map(PathBuf::from).unwrap_or(state),
            "--version" => {
                println!("r6-timers {}", env!("CARGO_PKG_VERSION"));
                return;
            }
            other => config = PathBuf::from(other),
        }
    }
    let text = std::fs::read_to_string(&config).unwrap_or_default();
    let cfg: Config = match toml::from_str(&text) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("r6-timers: {}: {e}", config.display());
            std::process::exit(1);
        }
    };
    if cfg.timer.is_empty() {
        eprintln!("r6-timers: no timers");
        // Nothing to do; stay up so the service does not restart-loop.
        loop {
            std::thread::sleep(Duration::from_secs(86400));
        }
    }
    let _ = std::fs::create_dir_all(&state);
    let r6 = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(|d| d.join("r6")))
        .unwrap_or_else(|| PathBuf::from("r6"));
    let started = now();
    let mut ran: std::collections::BTreeSet<String> = Default::default();
    for t in &cfg.timer {
        println!("{}: {} every {} s", t.name, t.service, t.interval_s);
    }
    loop {
        let t_now = now();
        let mut next_wake = t_now + 3600;
        for t in &cfg.timer {
            let Some(d) = due(t, last_run(&state, &t.name), started, ran.contains(&t.name)) else {
                continue;
            };
            if d <= t_now {
                println!("{}: starting {}", t.name, t.service);
                let ok = std::process::Command::new(&r6)
                    .args(["start", "--no-block", &t.service])
                    .status()
                    .map(|s| s.success())
                    .unwrap_or(false);
                if !ok {
                    eprintln!("{}: r6 start {} failed", t.name, t.service);
                }
                let _ = std::fs::write(state.join(&t.name), format!("{t_now}\n"));
                ran.insert(t.name.clone());
            } else {
                next_wake = next_wake.min(d);
            }
        }
        // Wake at least hourly (suspend and clock changes), at most once a second.
        let sleep = next_wake.saturating_sub(now()).clamp(1, 3600);
        std::thread::sleep(Duration::from_secs(sleep));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn t(interval: u64, persistent: bool) -> Timer {
        Timer {
            name: "x".into(),
            service: "x".into(),
            interval_s: interval,
            boot_delay_s: 300,
            persistent,
        }
    }

    #[test]
    fn schedule() {
        let boot = 1_000_000;
        // Never ran: one interval (capped at a day) after boot.
        assert_eq!(due(&t(3600, false), None, boot, false), Some(boot + 3600));
        assert_eq!(
            due(&t(604800, false), None, boot, false),
            Some(boot + 86400)
        );
        // Ran recently: last + interval.
        assert_eq!(
            due(&t(3600, false), Some(boot), boot, false),
            Some(boot + 3600)
        );
        // Missed while off: persistent catches up after the boot delay.
        assert_eq!(
            due(&t(3600, true), Some(boot - 7200), boot, false),
            Some(boot + 300)
        );
        assert_eq!(
            due(&t(3600, false), Some(boot - 7200), boot, false),
            Some(boot + 3600)
        );
        // Once per boot.
        assert_eq!(due(&t(0, false), None, boot, false), Some(boot + 300));
        assert_eq!(due(&t(0, false), None, boot, true), None);
    }
}
